18	// 結果の 3 つの値。D8 の条件 (1) が成り立つ・成り立たない・確認できない。
19	const (
20		holds        = "holds"
21		notHolds     = "not-holds"
22		unverifiable = "unverifiable"
23	)
24	
25	type result struct {
26		kind   string
27		reason string
28		lines  []lineResult // 行ごとの内訳。行を調べる前に結果が決まったときは空
29	}
30	
31	type lineResult struct {
32		line int
33		kind string
34		note string
35	}
36	
37	// check は、opts の行が全量の起点からレビューした内容まで変わっていないかを確認する。
38	// 入力の誤り (解決できない版・レビューした内容に無いファイルや行) は error で返し、結果にしない。
39	func check(opts options) (result, error) {
40		if err := checkGitVersion(opts.worktree); err != nil {
41			return result{}, err
42		}
43		top, err := toplevel(opts.root)
44		if err != nil {
45			return result{}, err
46		}
47		g := gitRunner{root: top}
48	
49		base, found, err := g.commit(opts.base)
50		if err != nil {
51			return result{}, err
52		} else if !found {
53			return result{}, inputf("-base をコミットに解決できません: %s", opts.base)
54		}
55		targetName := opts.rev
56		if opts.worktree {
57			targetName = "HEAD"
58		}
59		target, found, err := g.commit(targetName)
60		if err != nil {
61			return result{}, err
62		} else if !found {
63			return result{}, inputf("レビューした内容のコミット (%s) を解決できません", targetName)
64		}
65	
66		// 全量の起点がレビューした内容のコミットと同じなら、範囲 <起点>..<コミット> が空になり、
67		// コミット済みのどの行も起点にあったままと報告される。ブランチの変更と前からある行を区別できない。
68		// フラグ -allow-same-commit (判定ノード D9) では、起点は前の指摘を判定した回のコミットで、
69		// 確認するのは、そのコミットからレビューした内容までに行が変わっていないかである。同じコミットなら、
70		// コミット済みの行が起点にあったままと報告されるのが正しい結果なので、下の確認 (シンボリックリンク・
71		// 属性・コミットしていない変更) と git blame に進む。
72		if base == target && !opts.allowSameCommit {
73			return result{kind: unverifiable, reason: fmt.Sprintf("全量の起点 %s が、レビューした内容のコミット (%s) と同じで、このブランチの変更と前からある行を区別できない", short(base), targetName)}, nil
74		}
75		ok, err := g.isAncestor(base, target)
76		if err != nil {
77			return result{}, asRun(err)
78		}
79		if !ok {
80			return result{kind: unverifiable, reason: fmt.Sprintf("全量の起点 %s が、レビューした内容のコミット (%s) の祖先ではない", short(base), targetName)}, nil
81		}
82	
83		// 指摘の file は、レビューした内容にあるはず (根拠の照合 E1 を通っている)。無ければ入力の誤り。
84		targetEntry, err := g.entry(target, opts.file)
85		if err != nil {
86			return result{}, err
87		}
88		if opts.worktree {
89			st, err := os.Stat(filepath.Join(top, filepath.FromSlash(opts.file)))
90			if err != nil || !st.Mode().IsRegular() {
91				return result{}, inputf("作業ツリーに -file のファイルがありません: %s", opts.file)
92			}
93		} else if targetEntry != entryFile && targetEntry != entrySymlink {
94			return result{}, inputf("レビューした内容 (%s) に -file のファイルがありません: %s", opts.rev, opts.file)
95		}
96	
97		if baseEntry, err := g.entry(base, opts.file); err != nil {
98			return result{}, err
99		} else if baseEntry != entryFile && baseEntry != entrySymlink {
100			return result{kind: notHolds, reason: fmt.Sprintf("全量の起点 %s に同じパスのファイルが無い (このブランチで作った・改名した・移したファイル)", short(base))}, nil
101		}
102		if opts.worktree && targetEntry != entryFile && targetEntry != entrySymlink {
103			return result{kind: notHolds, reason: "HEAD に同じパスのファイルが無い (コミットしていないファイル)"}, nil
104		}
105	
106		// 次の 3 つは、レビュアが読む内容とコマンド git blame が見る内容が違いうる。シンボリックリンクと clean
107		// フィルタは行番号が対応せず、属性 ident は行の中の書き換えを、比べる前の変換で戻す。どれも書き換えた行が
108		// 起点のままと報告されうる (誤った holds) ので、方式によらず確認しない。
109		// git はシンボリックリンクのリンクの文字列を 1 行のブロブとして記録し、git blame もそれを見るが、
110		// レビュアはリンクの先の内容を読む
111		if targetEntry == entrySymlink {
112			return result{kind: unverifiable, reason: "指摘のファイルが追跡中のシンボリックリンクで、レビュアが読むリンクの先の内容と、git が記録するリンクの文字列の行番号が対応しない"}, nil
113		}
114		// clean フィルタは、作業ツリーの内容 (レビュアが読む、フィルタの前の内容) を変換してから記録し、
115		// git blame もフィルタの後の内容 (コミットの内容と、オプション --contents で渡した内容) を見る。フィルタが
116		// 行を増やしたり消したりすると、行番号がずれる。属性 ident は、記録するときに「$Id: … $」を「$Id$」へ戻し、
117		// コマンド git hash-object --path と git blame --contents も同じ変換を当ててから比べるので、「$Id: … $」の
118		// 中の書き換えが見えない。-rev では、コミットしていない変更の確認より前に、属性 filter と ident を調べる (その確認が実行する
119		// git hash-object --path が、フィルタのプログラムを実行しないように)
120		attr, err := g.convertingAttribute(opts.file)
121		if err != nil {
122			return result{}, err
123		}
124		switch attr {
125		case "filter":
126			return result{kind: unverifiable, reason: "指摘のファイルに clean フィルタ (属性 filter) が設定されていて、作業ツリーの内容 (フィルタの前) と、git blame が見るフィルタの後の内容の行番号がずれうる"}, nil
127		case "ident":
128			return result{kind: unverifiable, reason: "指摘のファイルに属性 ident が設定されていて、git は「$Id: … $」の中を「$Id$」へ戻してから内容を比べるので、レビュアが読んだその中の書き換えを確認できない"}, nil
129		}
130	
131		if !opts.worktree {
132			// 結果のファイルで受け取ったレビューは、共有の作業ツリーでコミットしていない変更を見た可能性があり、
133			// 結果のファイルからは分からない。ほかのファイルの変更は、指摘の file の行番号を変えないので見ない。
134			// 比べる相手は HEAD ではなく、レビューした内容のコミットにする。-rev が HEAD より前なら、レビューの
135			// 時点ではコミットしていなかった編集が、その後のコミットに入っていることがあり、HEAD と比べても見つからない
136			changed, err := g.hasUncommittedChange(top, target, targetEntry, opts.file)
137			if err != nil {
138				return result{}, asRun(err)
139			}
140			if changed {
141				return result{kind: unverifiable, reason: fmt.Sprintf("指摘のファイルの作業ツリーかインデックスの内容が、レビューした内容のコミット (%s) と違う (コミットしていない変更があるか、そのコミットより後のコミットで変わった) ので、レビューがどの内容を見たかが分からない", targetName)}, nil
142			}
143		}
144	
145		blamed, err := g.blame(base, target, opts)
146		if err != nil {
147			return result{}, err
148		}
149		return classify(base, opts.file, blamed), nil
150	}
151	
152	// classify は blame の結果を行ごとに分類し、全体の結果を決める。
153	// 成り立たない行が 1 つでもあれば成り立たない、無くて確認できない行があれば確認できない。
154	func classify(base, file string, blamed []blameLine) result {
155		res := result{kind: holds}
156		for _, b := range blamed {
157			l := lineResult{line: b.final}
158			switch {
159			case isZero(b.commit):
160				l.kind, l.note = notHolds, "コミットしていない行"
161			case !b.boundary:
162				l.kind, l.note = notHolds, fmt.Sprintf("全量の起点より後のコミット %s が書いた・書き換えた行", short(b.commit))
163			case b.commit != base:
164				// 起点より前に分かれた履歴をマージすると、行がその分岐点まで遡り、そこが境界になる。
165				// その行が起点にもあったかは、この結果からは決められない。
166				l.kind, l.note = unverifiable, fmt.Sprintf("全量の起点を通らない履歴 (起点より前に分かれた履歴のマージなど) から来た行で、境界のコミットが %s。全量の起点にあったかを決められない", short(b.commit))
167			case b.filename != file:
168				l.kind, l.note = notHolds, fmt.Sprintf("このブランチで改名・移動したファイルの行 (全量の起点では %s)", b.filename)
169			default:
170				// 境界が起点でパスも同じなので、フィールド orig は起点のファイルでの行番号
171				l.kind, l.note = holds, fmt.Sprintf("全量の起点にあったまま (起点の %d 行目)", b.orig)
172			}
173			res.lines = append(res.lines, l)
174			switch {
175			case l.kind == notHolds:
176				res.kind = notHolds
177			case l.kind == unverifiable && res.kind == holds:
178				res.kind = unverifiable
179			}
180		}
181		switch res.kind {
182		case notHolds:
183			res.reason = "対象の行のうち、全量の起点から変わった行がある"
184		case unverifiable:
185			res.reason = "対象の行のうち、全量の起点にあったかを決められない行がある"
186		default:
187			res.reason = fmt.Sprintf("対象の行はどれも、全量の起点 %s にあったまま変わっていない", short(base))
188		}
189		return res
190	}
