192	// lineCount は、レビューした内容の -file の行数を返す。数え方は git blame と同じで、
193	// 末尾に改行の無い最後の行も 1 行と数える。
194	func (g gitRunner) lineCount(target string, opts options) (int, error) {
195		var content []byte
196		if opts.worktree {
197			b, err := os.ReadFile(filepath.Join(g.root, filepath.FromSlash(opts.file)))
198			if err != nil {
199				return 0, runf("作業ツリーの -file を読めません: %v", err)
200			}
201			content = b
202		} else {
203			out, _, err := g.run("cat-file", "-p", target+":"+opts.file)
204			if err != nil {
205				return 0, asRun(err)
206			}
207			content = []byte(out)
208		}
209		n := bytes.Count(content, []byte("\n"))
210		if len(content) > 0 && content[len(content)-1] != '\n' {
211			n++
212		}
213		return n, nil
214	}
