216	type blameLine struct {
217		orig     int    // その行を最後に変えたコミット (範囲の外なら境界のコミット) の内容での行番号
218		final    int    // レビューした内容での行番号
219		commit   string // その行を最後に変えたコミット。範囲の外なら境界のコミット
220		boundary bool   // 範囲 <起点>..<コミット> の境界のコミットか
221		filename string // そのコミットでのパス
222	}
223	
224	var blameHeader = regexp.MustCompile(`^([0-9a-f]{40}|[0-9a-f]{64}) ([0-9]+) ([0-9]+)( [0-9]+)?$`)
225	
226	// parsePorcelain は git blame --line-porcelain の出力を読む。
227	func parsePorcelain(out string) ([]blameLine, error) {
228		var lines []blameLine
229		var cur *blameLine
230		for _, s := range strings.Split(out, "\n") {
231			if cur == nil {
232				if s == "" {
233					continue
234				}
235				m := blameHeader.FindStringSubmatch(s)
236				if m == nil {
237					return nil, fmt.Errorf("git blame の出力を読めません: %q", s)
238				}
239				orig, _ := strconv.Atoi(m[2])
240				final, _ := strconv.Atoi(m[3])
241				cur = &blameLine{orig: orig, final: final, commit: m[1]}
242				continue
243			}
244			switch {
245			case strings.HasPrefix(s, "\t"):
246				if cur.filename == "" {
247					return nil, fmt.Errorf("git blame の出力に行 %d のファイル名がありません", cur.final)
248				}
249				lines = append(lines, *cur)
250				cur = nil
251			case s == "boundary":
252				cur.boundary = true
253			case strings.HasPrefix(s, "filename "):
254				name, err := unquotePath(strings.TrimPrefix(s, "filename "))
255				if err != nil {
256					return nil, err
257				}
258				cur.filename = name
259			}
260		}
261		if cur != nil {
262			return nil, fmt.Errorf("git blame の出力が行 %d の途中で途切れています", cur.final)
263		}
264		return lines, nil
265	}
