267	// unquotePath は、git が引用符で囲んで出したパス (日本語や " を含むもの。例: "\346\227\245.md") を元に戻す。
268	func unquotePath(s string) (string, error) {
269		if !strings.HasPrefix(s, `"`) {
270			return s, nil
271		}
272		u, err := strconv.Unquote(s)
273		if err != nil {
274			return "", fmt.Errorf("git blame の出力のファイル名を読めません: %s", s)
275		}
276		return u, nil
277	}
278	
279	func isZero(sha string) bool { return strings.Trim(sha, "0") == "" }
280	
281	func short(sha string) string {
282		if len(sha) > 12 {
283			return sha[:12]
284		}
285		return sha
286	}
