288	// gitRunner は、リポジトリのルートを基準に git を実行する。
289	type gitRunner struct{ root string }
290	
291	// toplevel は -root からリポジトリのルートを求める。入力の誤りにするのは、-root が存在する
292	// ディレクトリでないときと、-root から上のどこにも .git が無いときだけ。.git があるのに git が
293	// リポジトリとして読めない (権限・所有者など) ときは、渡し方では直せないので run-error にする。
294	// git は .git を読めないときも「not a git repository」と言うので、.git の有無は道具が確認する。
295	func toplevel(dir string) (string, error) {
296		if st, err := os.Stat(dir); err != nil || !st.IsDir() {
297			return "", inputf("-root が存在するディレクトリではありません: %s", dir)
298		}
299		out, _, err := gitRunner{root: dir}.run("rev-parse", "--show-toplevel")
300		if err == nil {
301			// 出力の末尾の改行 1 つだけを落とす。名前の末尾の空白はパスの一部なので削らない (削ると、空白の無い
302			// 名前の別のディレクトリを読む)
303			return strings.TrimSuffix(out, "\n"), nil
304		}
305		var re *runError
306		if errors.As(err, &re) {
307			return "", err
308		}
309		if strings.Contains(err.Error(), "not a git repository") {
310			if dotGit, ok := findDotGit(dir); ok {
311				return "", runf("%s があるが、git がリポジトリとして読めません: %v", dotGit, err)
312			}
313			return "", inputf("-root が git のリポジトリの中を指していません: %s", dir)
314		}
315		return "", runf("-root のリポジトリを git で読めません: %v", err)
316	}
317	
318	// findDotGit は、dir から上のディレクトリをたどって、最初に見つかった .git (ディレクトリか、
319	// 作業ツリーが持つファイル) のパスを返す。
320	func findDotGit(dir string) (string, bool) {
321		for d := filepath.Clean(dir); ; d = filepath.Dir(d) {
322			p := filepath.Join(d, ".git")
323			if _, err := os.Lstat(p); err == nil {
324				return p, true
325			}
326			if filepath.Dir(d) == d {
327				return "", false
328			}
329		}
330	}
331	
332	// run は git を実行し、標準出力と終了コードを返す。終了コードが 0 でなければ error も返す。
333	//
334	// どのディレクトリから実行しても同じ結果になるよう、git のオプション -C でルートを指定する。環境は関数 gitEnv が作る。
335	func (g gitRunner) run(args ...string) (string, int, error) {
336		return g.runIn(nil, args...)
337	}
338	
339	// gitTimeout は、git の 1 回の実行に許す時間。越えたら run-error にする。git や、git が起動する
340	// フィルタのプログラムが応答しなくなったときに、道具が終了しなくなるのを防ぐ。テストが短くする。
341	var gitTimeout = 5 * time.Minute
342	
343	// runIn は、stdin を標準入力に渡して run と同じように git を実行する。
344	//
345	// 設定 core.fsmonitor は打ち消す。打ち消さないと、git はそこに登録したプログラムを起動し、値が true なら
346	// 常駐のプロセス git fsmonitor--daemon が .git の下にファイルを作って、道具が終了した後も残る。
347	func (g gitRunner) runIn(stdin io.Reader, args ...string) (string, int, error) {
348		ctx, cancel := context.WithTimeout(context.Background(), gitTimeout)
349		defer cancel()
350		cmd := exec.CommandContext(ctx, "git", append([]string{"-C", g.root, "-c", "core.quotePath=false", "-c", "core.fsmonitor=false"}, args...)...)
351		cmd.WaitDelay = time.Second // 期限で停止させた git の子のプロセスが出力を開いたままでも、待機し続けない
352		cmd.Env = gitEnv()
353		cmd.Stdin = stdin
354		var stdout, stderr bytes.Buffer
355		cmd.Stdout, cmd.Stderr = &stdout, &stderr
356		err := cmd.Run()
357		if ctx.Err() == context.DeadlineExceeded {
358			return "", -1, runf("git %s が %s 以内に終了しませんでした", strings.Join(args, " "), gitTimeout)
359		}
360		if err == nil {
361			return stdout.String(), 0, nil
362		}
363		var exitErr *exec.ExitError
364		if errors.As(err, &exitErr) {
365			return stdout.String(), exitErr.ExitCode(), fmt.Errorf("git %s: %s", strings.Join(args, " "), strings.TrimSpace(stderr.String()))
366		}
367		return "", -1, runf("git を起動できません: %v", err)
368	}
369	
370	var gitVersionRe = regexp.MustCompile(`^git version ([0-9]+)\.([0-9]+)`)
371	
372	// checkGitVersion は、git を起動できることと、道具が要る版であることを確認する。要るのは 2.30 以降
373	// (関数 commit が使うコマンド git rev-parse --end-of-options が 2.30.0 から) で、フラグ -worktree では
374	// 2.41 以降 (関数 blame がコマンド git blame にオプション --contents と範囲 <起点>..<コミット> を一緒に
375	// 渡す形を、git は 2.41.0 から受け付ける)。古い git では、正しい版を渡しても解決できないか、git blame が
376	// 毎回失敗するので、入力の誤りと取り違えないよう、道具を実行できないこととして返す。
377	func checkGitVersion(worktree bool) error {
378		ctx, cancel := context.WithTimeout(context.Background(), gitTimeout)
379		defer cancel()
380		cmd := exec.CommandContext(ctx, "git", "version")
381		cmd.WaitDelay = time.Second
382		cmd.Env = gitEnv()
383		out, err := cmd.Output()
384		if ctx.Err() == context.DeadlineExceeded {
385			return runf("git version が %s 以内に終了しませんでした", gitTimeout)
386		}
387		if err != nil {
388			return runf("git を起動できません: %v", err)
389		}
390		major, minor, ok := parseGitVersion(string(out))
391		if !ok {
392			return runf("git の版を読めません: %s", strings.TrimSpace(string(out)))
393		}
394		if major < 2 || major == 2 && minor < 30 {
395			return runf("git 2.30 以降が要ります (git rev-parse --end-of-options を使うため)。この git は %s", strings.TrimSpace(string(out)))
396		}
397		if worktree && major == 2 && minor < 41 {
398			return runf("フラグ -worktree には git 2.41 以降が要ります (git blame に --contents と範囲を一緒に渡すため)。この git は %s", strings.TrimSpace(string(out)))
399		}
400		return nil
401	}
402	
403	func parseGitVersion(s string) (major, minor int, ok bool) {
404		m := gitVersionRe.FindStringSubmatch(strings.TrimSpace(s))
405		if m == nil {
406			return 0, 0, false
407		}
408		major, _ = strconv.Atoi(m[1])
409		minor, _ = strconv.Atoi(m[2])
410		return major, minor, true
411	}
