527	// (通常のファイルをシンボリックリンクに置き換えたなど)、ハッシュを比べずに変更ありとする。ハッシュだけを
528	// 比べると、リンクの文字列がファイルの内容とちょうど同じときに、同じ内容と見なしてしまう。
529	func (g gitRunner) hasUncommittedChange(top, rev, kind, file string) (bool, error) {
530		committed, err := g.blob(rev, file)
531		if err != nil {
532			return false, err
533		}
534		out, _, err := g.run("ls-files", "--stage", "--", file)
535		if err != nil {
536			return false, err
537		}
538		// 項目のどれかのステージが 0 でなければ、変更ありとする。衝突の解消の途中は、インデックスに同じパスの
539		// 項目がステージ 1〜3 に分かれてあるので、これに当たる。項目の種類 (mode) が kind と違うときも変更ありとする
540		var index string
541		if out != "" {
542			for _, e := range strings.Split(strings.TrimSpace(out), "\n") {
543				fields := strings.Fields(e)
544				if len(fields) < 3 || fields[2] != "0" || modeKind(fields[0]) != kind {
545					return true, nil
546				}
547				index = fields[1]
548			}
549		}
550		// 作業ツリーの内容のハッシュを、git が記録するのと同じ形で求める。git が記録するのは通常の
551		// ファイルとシンボリックリンクだけで、シンボリックリンクはリンクの先ではなくリンクの文字列を記録する
552		var worktree string
553		abs := filepath.Join(top, filepath.FromSlash(file))
554		st, err := os.Lstat(abs)
555		switch {
556		case os.IsNotExist(err):
557			// 作業ツリーから消した。worktree は空のまま
558		case err != nil:
559			return false, runf("作業ツリーの -file を読めません: %v", err)
560		case st.Mode().IsRegular():
561			if kind != entryFile {
562				return true, nil
563			}
564			// --path で、そのパスの属性によるフィルタ (改行の変換など) を当ててからハッシュを求める。オプション -w を付けないので書き込まない
565			out, _, err := g.run("hash-object", "--path="+file, "--", abs)
566			if err != nil {
567				return false, err
568			}
569			worktree = strings.TrimSpace(out)
570		case st.Mode()&os.ModeSymlink != 0:
571			if kind != entrySymlink {
572				return true, nil
573			}
574			link, err := os.Readlink(abs)
575			if err != nil {
576				return false, runf("作業ツリーの -file のリンクを読めません: %v", err)
577			}
578			out, _, err := g.runIn(strings.NewReader(link), "hash-object", "--no-filters", "--stdin")
579			if err != nil {
580				return false, err
581			}
582			worktree = strings.TrimSpace(out)
583		default:
584			// ディレクトリなど、git が記録しない種類に置き換わっている
585			return true, nil
586		}
587		return committed != index || index != worktree, nil
588	}
