590	// convertingAttribute は、file に、レビュアが読む内容と git が比べる内容を違えうる属性が設定されて
591	// いれば、その名前 (filter か ident) を返す。無ければ空を返す。両方あれば filter を返す。
592	//
593	// 属性 filter (コマンド git add のときにファイルを変換するプログラム) の値はドライバ (設定
594	// filter.<名前>.clean などで登録する、変換のプログラムの名前) で、設定の無いドライバの名前や、値の無い
595	// filter も「あり」とする。
596	// 属性 ident (ファイルの中の「$Id$」を、取り出すときにブロブの SHA を入れた「$Id: … $」に展開し、記録する
597	// ときに「$Id$」へ戻す仕組み) は、unset 以外の値なら「あり」とする (git が展開するのは値が set のときだけ)。
598	// 「あり」なら呼び出し元は確認せずに unverifiable を返すので、迷う場合を「あり」として扱っても、
599	// 誤った holds にはならない。
600	func (g gitRunner) convertingAttribute(file string) (string, error) {
601		// オプション -a は、値のある属性 (unset を含む) だけを出し、属性が無い (unspecified) ものは出さない。
602		// filter だけを問い合わせると、属性が無いことと、名前が unspecified のドライバを同じ出力で返す
603		out, _, err := g.run("check-attr", "-a", "-z", "--", file)
604		if err != nil {
605			return "", asRun(err)
606		}
607		// オプション -z の出力は「<パス> NUL <属性> NUL <値> NUL」の繰り返しで、属性が無ければ空。NUL で分けると、
608		// 要素の数は 3 の倍数に 1 を足した数になり、最後は空になる。そうでない出力は読めないので run-error にする
609		// (読めない出力を属性無しとして扱い、git blame で行を調べに進むと、誤った holds になりうる)
610		parts := strings.Split(out, "\x00")
611		if len(parts)%3 != 1 || parts[len(parts)-1] != "" {
612			return "", runf("git check-attr の出力を読めません: %q", out)
613		}
614		ident := false
615		for k := 0; k+2 < len(parts); k += 3 {
616			switch parts[k+1] {
617			case "filter":
618				if parts[k+2] != "unset" {
619					return "filter", nil
620				}
621				// unset は、-filter (フィルタを外す) と、名前が unset のドライバを区別できないので、
622				// そのドライバの設定があれば「あり」とする
623				_, code, err := g.run("config", "--get-regexp", `^filter\.unset\.(clean|process)$`)
624				switch code {
625				case 0:
626					return "filter", nil
627				case 1:
628					// ドライバの設定が無いので、-filter (フィルタを外す)
629				default:
630					return "", asRun(err)
631				}
632			case "ident":
633				ident = parts[k+2] != "unset"
634			}
635		}
636		if ident {
637			return "ident", nil
638		}
639		return "", nil
640	}
