671		for _, r := range opts.ranges {
672			args = append(args, "-L", fmt.Sprintf("%d,%d", r.from, r.to))
673			want += r.to - r.from + 1
674		}
675		if opts.worktree {
676			args = append(args, "--contents", filepath.Join(g.root, filepath.FromSlash(opts.file)))
677		}
678		// 行がレビューした内容の行数を越えるのは渡し方の誤りなので、blame の前に道具が数えて
679		// input-error にする。blame そのものの失敗は、渡し方では説明できないので run-error にする
680		n, err := g.lineCount(target, opts)
681		if err != nil {
682			return nil, err
683		}
684		if last := opts.ranges[len(opts.ranges)-1].to; last > n {
685			return nil, inputf("行 %d が、レビューした内容の -file の行数 (%d) を越えます", last, n)
686		}
687		args = append(args, base+".."+target, "--", opts.file)
688		out, _, err := g.run(args...)
689		if err != nil {
690			return nil, asRun(err)
691		}
692		lines, err := parsePorcelain(out)
693		if err != nil {
694			return nil, asRun(err)
695		}
696		if len(lines) != want {
697			return nil, runf("git blame が %d 行を返しました (求めたのは %d 行)", len(lines), want)
698		}
699		return lines, nil
